import Dexie, { Table } from 'dexie';

export interface User {
  id?: number;
  email: string;
  password: string;
  name: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface Conta {
  id?: number;
  userId: number;
  descricao: string;
  valor: number;
  dataVencimento: Date;
  dataPagamento?: Date;
  categoria: string;
  status: 'pendente' | 'pago' | 'recebido' | 'atrasado';
  tipo: 'pagar' | 'receber';
  observacoes?: string;
  createdAt: Date;
  updatedAt: Date;
}

export class FinanceDatabase extends Dexie {
  users!: Table<User>;
  contas!: Table<Conta>;

  constructor() {
    super('FinanceDB');
    this.version(2).stores({
      users: '++id, email',
      contas: '++id, userId, descricao, categoria, status, tipo, dataVencimento, createdAt'
    });
  }
}

export const db = new FinanceDatabase();

// Funções de autenticação
export const auth = {
  async register(email: string, password: string, name: string): Promise<User> {
    const existingUser = await db.users.where('email').equals(email).first();
    if (existingUser) {
      throw new Error('Usuário já existe');
    }

    const now = new Date();
    const userId = await db.users.add({
      email,
      password, // Em produção, use hash!
      name,
      createdAt: now,
      updatedAt: now,
    });

    const user = await db.users.get(userId);
    if (!user) throw new Error('Erro ao criar usuário');
    
    return user;
  },

  async login(email: string, password: string): Promise<User> {
    const user = await db.users.where('email').equals(email).first();
    if (!user) {
      throw new Error('Usuário não encontrado');
    }

    if (user.password !== password) {
      throw new Error('Senha incorreta');
    }

    // Salvar sessão
    localStorage.setItem('currentUser', JSON.stringify({
      id: user.id,
      email: user.email,
      name: user.name,
    }));

    return user;
  },

  logout(): void {
    localStorage.removeItem('currentUser');
  },

  getCurrentUser(): { id: number; email: string; name: string } | null {
    if (typeof window === 'undefined') return null;
    const userStr = localStorage.getItem('currentUser');
    return userStr ? JSON.parse(userStr) : null;
  },

  isAuthenticated(): boolean {
    return this.getCurrentUser() !== null;
  }
};

export const contasPagar = {
  async getAll(userId: number): Promise<Conta[]> {
    return await db.contas
      .where({ userId, tipo: 'pagar' })
      .reverse()
      .sortBy('createdAt');
  },

  async getById(id: number, userId: number): Promise<Conta | undefined> {
    return await db.contas.where({ id, userId }).first();
  },

  async getByStatus(status: string, userId: number): Promise<Conta[]> {
    return await db.contas
      .where({ userId, tipo: 'pagar', status })
      .toArray();
  },

  async getPendentes(userId: number): Promise<Conta[]> {
    return await db.contas
      .where({ userId, tipo: 'pagar', status: 'pendente' })
      .toArray();
  },

  async getAtrasadas(userId: number): Promise<Conta[]> {
    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);
    
    const pendentes = await this.getPendentes(userId);
    return pendentes.filter(conta => {
      const vencimento = new Date(conta.dataVencimento);
      return vencimento < hoje;
    });
  },

  async create(conta: Omit<Conta, 'id' | 'createdAt' | 'updatedAt'>): Promise<number> {
    const now = new Date();
    return await db.contas.add({
      ...conta,
      createdAt: now,
      updatedAt: now,
    });
  },

  async update(id: number, userId: number, conta: Partial<Conta>): Promise<void> {
    const existing = await this.getById(id, userId);
    if (!existing) throw new Error('Conta não encontrada');
    
    await db.contas.update(id, {
      ...conta,
      updatedAt: new Date(),
    });
  },

  async delete(id: number, userId: number): Promise<void> {
    const existing = await this.getById(id, userId);
    if (!existing) throw new Error('Conta não encontrada');
    
    await db.contas.delete(id);
  },

  async getTotalPendente(userId: number): Promise<number> {
    const pendentes = await this.getPendentes(userId);
    return pendentes.reduce((total, conta) => total + conta.valor, 0);
  },

  async getTotalPago(userId: number, mes?: number, ano?: number): Promise<number> {
    const pagos = await this.getByStatus('pago', userId);
    
    if (mes !== undefined && ano !== undefined) {
      const filtrados = pagos.filter(conta => {
        if (!conta.dataPagamento) return false;
        const data = new Date(conta.dataPagamento);
        return data.getMonth() === mes && data.getFullYear() === ano;
      });
      return filtrados.reduce((total, conta) => total + conta.valor, 0);
    }
    
    return pagos.reduce((total, conta) => total + conta.valor, 0);
  }
};

